//! Raw NVENC and CUDA driver API declarations.
//!
//! `nvenc_api` is generated by bindgen from FFmpeg's nv-codec-headers (the NVIDIA
//! Video Codec SDK 12.1 header, MIT licence: "Copyright (c) 2010-2023 NVIDIA
//! Corporation", full notice in the generated file's source header). Its layout
//! assertions are compile-time, so a target whose ABI differs from the one the
//! bindings were generated on (Linux x86_64) fails to build instead of passing wrong
//! structures to the driver. The header's macros and `static const GUID`s are not
//! generated; they are written out below.

#![allow(
    non_camel_case_types,
    non_snake_case,
    non_upper_case_globals,
    dead_code,
    missing_docs,
    unnecessary_transmutes,
    unused_imports,
    clippy::all,
    clippy::undocumented_unsafe_blocks
)]

#[rustfmt::skip]
pub(crate) mod nvenc_api;

pub(crate) use nvenc_api::*;

/// `NVENCAPI_VERSION` of SDK 12.1.
pub(crate) const API_VERSION: u32 = 12 | (1 << 24);
/// `(major << 4) | minor` as `NvEncodeAPIGetMaxSupportedVersion` reports it; drivers
/// below this cannot run SDK 12.1 sessions.
pub(crate) const MIN_DRIVER_API: u32 = (12 << 4) | 1;

/// `NVENCAPI_STRUCT_VERSION(ver)`.
const fn struct_version(ver: u32) -> u32 {
    API_VERSION | (ver << 16) | (0x7 << 28)
}

pub(crate) const NV_ENCODE_API_FUNCTION_LIST_VER: u32 = struct_version(2);
pub(crate) const NV_ENC_OPEN_ENCODE_SESSION_EX_PARAMS_VER: u32 = struct_version(1);
pub(crate) const NV_ENC_CAPS_PARAM_VER: u32 = struct_version(1);
pub(crate) const NV_ENC_CREATE_INPUT_BUFFER_VER: u32 = struct_version(1);
pub(crate) const NV_ENC_CREATE_BITSTREAM_BUFFER_VER: u32 = struct_version(1);
pub(crate) const NV_ENC_RC_PARAMS_VER: u32 = struct_version(1);
pub(crate) const NV_ENC_CONFIG_VER: u32 = struct_version(8) | (1 << 31);
pub(crate) const NV_ENC_INITIALIZE_PARAMS_VER: u32 = struct_version(6) | (1 << 31);
pub(crate) const NV_ENC_RECONFIGURE_PARAMS_VER: u32 = struct_version(1) | (1 << 31);
pub(crate) const NV_ENC_PRESET_CONFIG_VER: u32 = struct_version(4) | (1 << 31);
pub(crate) const NV_ENC_PIC_PARAMS_VER: u32 = struct_version(6) | (1 << 31);
pub(crate) const NV_ENC_LOCK_BITSTREAM_VER: u32 = struct_version(1) | (1 << 31);
pub(crate) const NV_ENC_LOCK_INPUT_BUFFER_VER: u32 = struct_version(1);
pub(crate) const NV_ENC_SEQUENCE_PARAM_PAYLOAD_VER: u32 = struct_version(1);

const fn guid(d1: u32, d2: u16, d3: u16, d4: [u8; 8]) -> GUID {
    GUID {
        Data1: d1,
        Data2: d2,
        Data3: d3,
        Data4: d4,
    }
}

