/// True when two GUIDs are equal (the generated struct has no `PartialEq`).
pub(crate) fn same_guid(a: &GUID, b: &GUID) -> bool {
    (a.Data1, a.Data2, a.Data3, a.Data4) == (b.Data1, b.Data2, b.Data3, b.Data4)
}

/// `NvEncodeAPICreateInstance`.
pub(crate) type CreateInstanceFn =
    unsafe extern "system" fn(list: *mut NV_ENCODE_API_FUNCTION_LIST) -> NVENCSTATUS;
/// `NvEncodeAPIGetMaxSupportedVersion`.
pub(crate) type MaxVersionFn = unsafe extern "system" fn(version: *mut u32) -> NVENCSTATUS;

/// CUDA driver API (`cuda.h`), the few calls the adapter needs. `CUresult` 0 is
/// `CUDA_SUCCESS`.
pub(crate) mod cuda {
    use core::ffi::{c_char, c_int, c_uint, c_void};

    pub(crate) type CUresult = c_int;
    pub(crate) type CUdevice = c_int;
    pub(crate) type CUcontext = *mut c_void;

    pub(crate) const CUDA_SUCCESS: CUresult = 0;
    /// `CU_CTX_SCHED_BLOCKING_SYNC`: wait for the GPU without spinning a CPU core.
    pub(crate) const CU_CTX_SCHED_BLOCKING_SYNC: c_uint = 0x04;

    pub(crate) type InitFn = unsafe extern "system" fn(flags: c_uint) -> CUresult;
    pub(crate) type DeviceGetCountFn = unsafe extern "system" fn(count: *mut c_int) -> CUresult;
    pub(crate) type DeviceGetFn =
        unsafe extern "system" fn(device: *mut CUdevice, ordinal: c_int) -> CUresult;
    pub(crate) type DeviceGetNameFn =
        unsafe extern "system" fn(name: *mut c_char, len: c_int, device: CUdevice) -> CUresult;
    pub(crate) type CtxCreateFn =
        unsafe extern "system" fn(ctx: *mut CUcontext, flags: c_uint, device: CUdevice) -> CUresult;
    pub(crate) type CtxDestroyFn = unsafe extern "system" fn(ctx: CUcontext) -> CUresult;
    pub(crate) type CtxPushCurrentFn = unsafe extern "system" fn(ctx: CUcontext) -> CUresult;
    pub(crate) type CtxPopCurrentFn = unsafe extern "system" fn(ctx: *mut CUcontext) -> CUresult;
}
